import * as console from "std/console";

class State {
  pos: int = 0;
  vel: int = 0;
  acc: int = 0;
}

export function main(): null {
  let state: State = { pos: 0, vel: 3, acc: 1 };
  let ticks: int = 5;
  let i: int = 0;

  while (i < ticks) {
    // Euler integration:
    // v_new = v_old + a * dt
    // p_new = p_old + v_new * dt
    // (Using semi-implicit Euler for deterministic integer steps)
    state.vel = state.vel + state.acc;
    state.pos = state.pos + state.vel;
    i = i + 1;
  }

  let expected_pos: int = 25;
  let expected_vel: int = 8;

  if (state.pos!== expected_pos || state.vel!== expected_vel) {
    throw { code: "CHECK_FAILED", message: "physics simulation mismatch" };
  }

  console.log("physics-engine-1d-1:ok");
  return null;
}

import * as console from "std/console";

function simulate(position: int, velocity: int, acceleration: int, steps: int): table {
  let p: int = position;
  let v: int = velocity;
  for (let tick: int = 0; tick < steps; tick = tick + 1) {
    p = p + v;
    v = v + acceleration;
  }
  return { position: p, velocity: v };
}

export function main(): null {
  let state: table = simulate(0, 3, 1, 5);
  let finalPosition: int = state.position;
  let finalVelocity: int = state.velocity;
  if (finalPosition !== 25 || finalVelocity !== 8) {
    throw { code: "PHYSICS_FAIL", message: "integration mismatch" };
  }
  console.log("physics-engine-1d-1:ok");
  return null;
}

import * as console from "std/console";

class State {
  position: int = 0;
  velocity: int = 0;
  acceleration: int = 0;
}

function integrate(initial: State, ticks: int): State {
  let current: State = {
    position: initial.position,
    velocity: initial.velocity,
    acceleration: initial.acceleration
  };

  let i: int = 0;
  while (i < ticks) {
    // Update position using current velocity: p = p + v
    current.position = current.position + current.velocity;
    // Update velocity using acceleration: v = v + a
    current.velocity = current.velocity + current.acceleration;
    i = i + 1;
  }

  return current;
}

export function main(): null {
  let initial: State = {
    position: 10,
    velocity: -2,
    acceleration: 2
  };

  let final: State = integrate(initial, 4);

  let expectedPosition: int = 14;
  let expectedVelocity: int = 6;

  if (final.position !== expectedPosition) {
    throw { code: "POSITION_ERROR", message: "position mismatch" };
  }

  if (final.velocity !== expectedVelocity) {
    throw { code: "VELOCITY_ERROR", message: "velocity mismatch" };
  }

  console.log("physics-engine-1d-2:ok");
  return null;
}

