import * as console from "std/console";

class Rect {
  x: int = 0;
  y: int = 0;
  w: int = 0;
  h: int = 0;
}

function checkAABB(a: Rect, b: Rect): boolean {
  let aLeft: int = a.x;
  let aRight: int = a.x + a.w;
  let aTop: int = a.y;
  let aBottom: int = a.y + a.h;

  let bLeft: int = b.x;
  let bRight: int = b.x + b.w;
  let bTop: int = b.y;
  let bBottom: int = b.y + b.h;

  let overlapX: boolean = aLeft < bRight && aRight > bLeft;
  let overlapY: boolean = aTop < bBottom && aBottom > bTop;

  if (overlapX && overlapY) {
    return true;
  }
  return false;
}

export function main(): null {
  let rectA: Rect = { x: 0, y: 0, w: 4, h: 4 };
  let rectB: Rect = { x: 2, y: 2, w: 3, h: 3 };

  let isColliding: boolean = checkAABB(rectA, rectB);

  if (isColliding !== true) {
    throw { code: "CHECK_FAILED", message: "Expected collision for A=[0,0,4,4] and B=[2,2,3,3]" };
  }

  let rectC: Rect = { x: 4, y: 0, w: 2, h: 2 };
  let isTouching: boolean = checkAABB(rectA, rectC);

  if (isTouching !== false) {
    throw { code: "CHECK_FAILED", message: "Touching edges should not count as overlap" };
  }

  console.log("collision-aabb-1:ok");
  return null;
}

