}

function overlaps(a: Rect, b: Rect): boolean {
  let horizontal: boolean = a.x < b.x + b.width && b.x < a.x + a.width;
  let vertical: boolean = a.y < b.y + b.height && b.y < a.y + a.height;
  return horizontal && vertical;
}

