function checkAABB(a: Rect, b: Rect): boolean {
  let noOverlap: boolean = false;

  if (a.x + a.w <= b.x) {
    noOverlap = true;
  }
  if (b.x + b.w <= a.x) {
    noOverlap = true;
  }
  if (a.y + a.h <= b.y) {
    noOverlap = true;
  }
  if (b.y + b.h <= a.y) {
    noOverlap = true;
  }

  if (noOverlap === true) {
    return false;
  } else {
    return true;
  }
}

