class ParticleSystem {
  positions: int[] = [0, 10, -4];
  velocities: int[] = [2, -1, 3];
}

export function main(): null {
  let system: ParticleSystem = { positions: [0, 10, -4], velocities: [2, -1, 3] };
  let ticks: int = 3;
  let t: int = 0;

  while (t < ticks) {
    let i: int = 0;
    for (let i: int of [0, 1, 2]) {
      system.positions[i] = system.positions[i] + system.velocities[i];
    }
    t = t + 1;
  }

  let checksum: int = 0;
  let j: int = 0;
  for (let j: int of [0, 1, 2]) {
    checksum = checksum + system.positions[j];
  }

  if (checksum === 18) {
    console.log("particle-system-1:ok");
  } else {
    throw { code: "ERROR", message: "checksum mismatch" };
  }

  return null;
}

import * as console from "std/console";

function advance(positions: int[], velocities: int[], steps: int): int[] {
  let tick: int = 0;
  while (tick < steps) {
    for (let i: int = 0; i < positions.length; i = i + 1) {
      positions[i] = positions[i] + velocities[i];
    }
    tick = tick + 1;
  }
  return positions;
}

function sum(values: int[]): int {
  let result: int = 0;
  for (let value: int of values) { result = result + value; }
  return result;
}

export function main(): null {
  let positions: int[] = [0, 10, -4];
  let velocities: int[] = [2, -1, 3];
  let finalPositions: int[] = advance(positions, velocities, 3);
  if (sum(finalPositions) !== 18) {
    throw { code: "PARTICLE_FAIL", message: "particle checksum mismatch" };
  }
  console.log("particle-system-1:ok");
  return null;
}

import * as console from "std/console";

class Particle {
  position: int = 0;
  velocity: int = 0;
}

export function main(): null {
  let initialPositions: int[] = [5, 5, 5, 5];
  let velocities: int[] = [1, 2, 3, 4];
  let particles: Particle[] = [];
  let i: int = 0;

  while (i < initialPositions.length) {
    let p: Particle = { position: initialPositions[i], velocity: velocities[i] };
    particles = particles.push(p); // Note: DEAL doesn't have push, we must build manually
    i = i + 1;
  }

  // Correct way to build array in DEAL without push:
  let p0: Particle = { position: 5, velocity: 1 };
  let p1: Particle = { position: 5, velocity: 2 };
  let p2: Particle = { position: 5, velocity: 3 };
  let p3: Particle = { position: 5, velocity: 4 };
  let particleList: Particle[] = [p0, p1, p2, p3];

  let ticks: int = 2;
  let t: int = 0;
  while (t < ticks) {
    let j: int = 0;
    while (j < particleList.length) {
      let p: Particle = particleList[j];
      p.position = p.position + p.velocity;
      j = j + 1;
    }
    t = t + 1;
  }

  let checksum: int = 0;
  let k: int = 0;
  while (k < particleList.length) {
    checksum = checksum + particleList[k].position;
    k = k + 1;
  }

  if (checksum === 40) {
    console.log("particle-system-2:ok");
  }

  return null;
}

