        }
        // Add from left
        if (curr_c > 0) {
          let left_idx: int = curr_r * cols + (curr_c - 1);
          if (left_idx !== blocked_idx) {
            data[idx] = data[idx] + data[left_idx];
          }
        }
        // Special case for start cell: if we already set it to 1, 
        // the logic above might double count if not careful.
        // Let's refine:
        if (curr_r === 0 && curr_c === 0) {
          data[idx] = 1;
        } else {
          // Re-calculate to avoid logic errors
          let val: int = 0;
          if (curr_r > 0) {
            let t_idx: int = (curr_r - 1) * cols + curr_c;
            if (t_idx !== blocked_idx) {
              val = val + data[t_idx];
            }
          }
          if (curr_c > 0) {
            let l_idx: int = curr_r * cols + (curr_c - 1);
            if (l_idx !== blocked_idx) {
              val = val + data[l_idx];
            }
          }
          data[idx] = val;
        }
      }

      // Re-apply blocked logic to ensure it's 0
      if (idx === blocked_idx) {
        data[idx] = 0;
      }

      curr_c = curr_c + 1;
    }
    curr_r = curr_r + 1;
  }

  return data[size - 1];
}

